// NON-SENSITIVE PUBLIC SCHOLARLY EXAMPLES for UI evaluation. No private notes, ideas, or DB snapshot.
// Loaded only after the Phase 1 gate succeeds. This file is intentionally safe to serve as a static asset.
import {series,pair as p} from './atlas-data.js';
const ref=(title,url)=>({title,url});
const refs={
 lenet:ref('Gradient-Based Learning Applied to Document Recognition (1998)','https://doi.org/10.1109/5.726791'),
 alexnet:ref('ImageNet Classification with Deep Convolutional Neural Networks (2012)','https://papers.nips.cc/paper/4824-imagenet-classification-with-deep-convolutional-neural-networks'),
 vgg:ref('Very Deep Convolutional Networks for Large-Scale Image Recognition (2014 preprint)','https://arxiv.org/abs/1409.1556'),
 resnet:ref('Deep Residual Learning for Image Recognition (2015 preprint)','https://arxiv.org/abs/1512.03385'),
 vae:ref('Auto-Encoding Variational Bayes (2013 preprint)','https://arxiv.org/abs/1312.6114'),
 gan:ref('Generative Adversarial Nets (2014)','https://arxiv.org/abs/1406.2661'),
 ddpm:ref('Denoising Diffusion Probabilistic Models (2020)','https://arxiv.org/abs/2006.11239'),
 ldm:ref('High-Resolution Image Synthesis with Latent Diffusion Models (2021 preprint)','https://arxiv.org/abs/2112.10752'),
 world:ref('World Models (2018)','https://arxiv.org/abs/1803.10122'),
 planet:ref('Learning Latent Dynamics for Planning from Pixels (2018 preprint)','https://arxiv.org/abs/1811.04551'),
 dreamer:ref('Dream to Control: Learning Behaviors by Latent Imagination (2019 preprint)','https://arxiv.org/abs/1912.01603'),
 dreamerv3:ref('Mastering Diverse Domains through World Models (2023 preprint)','https://arxiv.org/abs/2301.04104')
};
const chains=[
 {id:'cnn-features',slug:'cnn-features',series_id:'neural-networks-cnns',title:p('Học đặc trưng & Độ sâu','Feature learning & depth'),description:p('Đối chiếu tích chập, năng lực mô hình và khả năng tối ưu. Đây là các mốc chọn lọc, không phải lịch sử đầy đủ.','Compare convolution, capacity, and trainability. These are selected milestones, not a complete history.')},
 {id:'generative-objectives',slug:'generative-objectives',series_id:'generative-models',title:p('Các nhánh mục tiêu sinh','Branches of generative objectives'),description:p('VAE, GAN và diffusion là những nhánh khác nhau. Thứ tự năm không tạo quan hệ kế thừa.','VAE, GAN, and diffusion are different branches. Publication order does not establish inheritance.')},
 {id:'latent-control',slug:'latent-control',series_id:'world-models',title:p('Động lực học ẩn & Điều khiển','Latent dynamics & control'),description:p('Từ nén quan sát đến lập kế hoạch và học hành vi trong tưởng tượng. Không đồng nhất dự đoán ảnh với hiểu vật lý.','From compressed observations to planning and imagined behavior learning. Image prediction is not equivalent to physical understanding.')}
];
const models=[];
function model(id,title,year,chain,sections){
 models.push({id,slug:id,title,year,chain_id:chain,summary:sections.insight,sections,evidence:[refs[id]],position:models.length});
}
model('lenet','LeNet-5',1998,'cnn-features',{
 insight:p('LeNet-5 học đặc trưng trực tiếp từ ảnh chữ số thay vì dựa hoàn toàn vào đặc trưng do con người thiết kế. Tích chập tái sử dụng cùng trọng số ở nhiều vị trí. Các tầng sau kết hợp dấu nét cục bộ thành biểu diễn hữu ích cho phân loại; đây không phải cơ chế nhận biết mọi vật thể.','LeNet-5 learns features from digit images rather than relying entirely on hand-designed descriptors. Convolution reuses weights across locations. Later stages combine local strokes into representations useful for classification; this is not a general mechanism for recognizing every object.'),
 origins:p('Nguồn gốc gồm kết nối cục bộ, chia sẻ trọng số và học bằng gradient. Các nguyên lý này tạo thiên kiến quy nạp: cấu trúc cục bộ giống nhau có thể xuất hiện ở nhiều vị trí. Bài báo cũng bàn về hệ thống nhận dạng tài liệu rộng hơn kiến trúc LeNet-5.','Local connectivity, shared weights, and gradient-based learning supply its foundations. The inductive bias is that useful local patterns can occur in different places. The paper discusses document-recognition systems beyond the LeNet-5 architecture itself.'),
 gap:p('Đặc trưng thủ công tách việc thiết kế biểu diễn khỏi việc học bộ phân loại. LeNet-5 kết hợp hai phần trong mạng có thể huấn luyện. Vấn đề được xét là nhận dạng tài liệu; không nên suy rộng kết quả chữ số sang ảnh tự nhiên phức tạp.','Hand-crafted pipelines separate representation design from classifier fitting. LeNet-5 brings them together in a trainable network. Its task is document recognition; digit results should not be extrapolated to complex natural images.'),
 mechanism:p('Luồng chính gồm tích chập, giảm mẫu, các tầng kết hợp và đầu ra phân loại. LeNet-5 gốc không phải bản CNN hiện đại chỉ dùng ReLU và max pooling: tầng giảm mẫu và tầng đầu ra có thiết kế riêng. Khi tái hiện, hãy ghi rõ khác biệt giữa bản gốc và bản đơn giản hóa.','Convolution, subsampling, feature combination, and classification form the main flow. Original LeNet-5 is not a modern ReLU/max-pooling stack: its subsampling and output stages have their own design. A reproduction should state where it simplifies the original.'),
 training:p('Ví dụ học có giám sát dùng ảnh chữ số và nhãn. Chia riêng tập đánh giá, chuẩn hóa ảnh nhất quán và theo dõi lỗi phân loại. Thực nghiệm học nhỏ có thể so sánh MLP và CNN trên cùng phép chia; đó là đề xuất kiểm tra, không phải số liệu mới của bài báo.','Supervised learning uses digit images and labels. Keep evaluation separate, normalize images consistently, and monitor classification errors. A small exercise can compare an MLP and a CNN on the same split; this is a proposed check, not a new result reported by the paper.'),
 results:p('Bài báo cung cấp bằng chứng cho học đặc trưng bằng gradient trong nhận dạng tài liệu. Khả năng bất biến chỉ có giới hạn: thay đổi góc nhìn, nền hoặc miền dữ liệu vẫn có thể gây lỗi. Cần đọc thiết lập đánh giá trước khi so sánh với mô hình hiện đại.','The paper supplies evidence for gradient-based feature learning in document recognition. Its invariance is limited: viewpoint, background, or domain changes can still cause errors. Read the evaluation setup before comparing it with modern networks.'),
 next:p('AlexNet tiếp tục khai thác CNN ở quy mô ảnh tự nhiên lớn hơn, với thay đổi đáng kể về dữ liệu, phần cứng và huấn luyện. Câu hỏi nghiên cứu minh họa: phần nào của độ bền đến từ kiến trúc, phần nào đến từ tăng cường dữ liệu? Kiểm tra từng yếu tố riêng thay vì chỉ tăng số tầng.','AlexNet later uses CNNs at natural-image scale with major changes in data, hardware, and training. An illustrative research question is how much robustness comes from architecture versus augmentation. Test the factors separately rather than merely increasing depth.')
});
model('alexnet','AlexNet',2012,'cnn-features',{
 insight:p('AlexNet cho thấy học đặc trưng bằng CNN có thể hiệu quả trên bài toán phân loại ảnh quy mô lớn khi kết hợp dữ liệu, GPU và cách huấn luyện phù hợp. Đóng góp không nằm ở việc phát minh tích chập; giá trị là hệ thống thực nghiệm làm cho mạng lớn có thể học và tổng quát hóa.','AlexNet shows that CNN feature learning can work at large image-classification scale when combined with data, GPUs, and suitable training. It does not invent convolution; the contribution is an empirical system that makes a large network learn and generalize.'),
 origins:p('Mô hình kế thừa truyền thống mạng tích chập và học lan truyền ngược. ReLU giúp tối ưu khác với các hàm kích hoạt bão hòa. Dropout và tăng cường dữ liệu giải quyết nguy cơ quá khớp; không nên coi chúng là bằng chứng rằng kích thước mạng tự bảo đảm chất lượng.','It builds on convolutional networks and backpropagation. ReLU changes optimization relative to saturating activations. Dropout and augmentation address overfitting; they do not imply that model size alone guarantees quality.'),
 gap:p('Ảnh tự nhiên có biến thiên lớn hơn chữ số chuẩn hóa. Các cách dùng đặc trưng thủ công hạn chế khả năng học biểu diễn theo dữ liệu. Bài báo kiểm tra CNN lớn trên ImageNet với nguồn lực tính toán cụ thể, không chứng minh ưu thế trong mọi chế độ dữ liệu nhỏ.','Natural images vary more than normalized digits. Hand-crafted features constrain what representations can be learned from data. The paper tests a large CNN on ImageNet under a specific compute setting, not superiority in every small-data regime.'),
 mechanism:p('Năm tầng tích chập và ba tầng fully connected xử lý ảnh rồi dự đoán nhãn. ReLU, pooling và regularization hỗ trợ mạng sâu hơn; triển khai GPU là một phần quan trọng. Thiết kế gốc chia tính toán giữa hai GPU, nên bản thư viện hiện nay có thể khác chi tiết.','Five convolutional and three fully connected layers map images to labels. ReLU, pooling, and regularization support the deeper network; GPU implementation matters. The original distributes computation across two GPUs, so modern library variants can differ in details.'),
 training:p('Huấn luyện có giám sát dùng ImageNet, tăng cường ảnh và tối ưu gradient theo minibatch. Khi tái hiện, cố định phép chia, ngân sách tính toán và lịch học. So sánh công bằng cần phân biệt dự đoán một crop, nhiều crop và tổ hợp mô hình.','Supervised ImageNet training uses image augmentation and minibatch gradient optimization. A reproduction should fix splits, compute budget, and schedule. Fair comparisons distinguish single-crop predictions, multi-crop evaluation, and model ensembles.'),
 results:p('Kết quả ImageNet hỗ trợ giá trị của hệ thống CNN lớn trong bối cảnh đó. Không nên ghép trực tiếp các tỷ lệ lỗi của tập dữ liệu hoặc giao thức khác nhau. Mô hình vẫn tốn tài nguyên, nhạy với phân phối ảnh và không cung cấp hiểu biết nhân quả về cảnh.','ImageNet results support the value of the large-CNN system in that setting. Error rates from different datasets or protocols should not be mixed directly. It remains resource-intensive, sensitive to image distributions, and does not provide causal scene understanding.'),
 next:p('VGG khảo sát chiều sâu bằng thiết kế tích chập đều hơn; ResNet sau đó giải quyết khó khăn tối ưu khi mạng sâu lên. Một thử nghiệm hữu ích là kiểm soát dữ liệu và regularization trước khi quy mọi cải thiện cho số tầng. Đây là hướng phân tích, không phải tuyên bố kết quả mới.','VGG studies depth with more uniform convolutions; ResNet later addresses optimization as depth increases. A useful investigation controls data and regularization before attributing every gain to layer count. This is an analytical direction, not a new experimental claim.')
});
model('vgg','VGG',2014,'cnn-features',{
 insight:p('VGG khảo sát liệu tăng chiều sâu với các tích chập nhỏ, lặp lại có cải thiện biểu diễn ảnh hay không. Thiết kế đều đặn làm quan hệ giữa chiều sâu và hiệu quả dễ kiểm tra hơn. Năm 2014 ở đây là năm bản thảo đầu tiên; bài báo được công bố tại ICLR 2015.','VGG asks whether increasing depth with repeated small convolutions improves image representations. Its uniform design makes the role of depth easier to examine. Here 2014 denotes the initial preprint; the paper appeared at ICLR 2015.'),
 origins:p('Tích chập và phi tuyến được xếp chồng để tăng vùng tiếp nhận hiệu dụng. Nhiều tầng 3×3 không tương đương một tầng lớn: chúng thêm phi tuyến và thay đổi tham số hóa. Giữ các lựa chọn khác gần nhau giúp kiểm tra tác động của chiều sâu.','Stacked convolutions and nonlinearities expand the effective receptive field. Multiple 3×3 layers are not equivalent to one large layer: they add nonlinearities and change parameterization. Similar surrounding choices help isolate depth.'),
 gap:p('Các mạng trước đó có tổ hợp kích thước bộ lọc và cấu trúc phức tạp hơn. VGG dùng cách thiết kế đơn giản để khảo sát mạng sâu, nhưng chưa giải quyết đầy đủ khó khăn tối ưu ở độ sâu rất lớn. Đây là một nhánh phát triển CNN, không phải nguồn gốc của mọi mô hình sâu.','Earlier networks used more varied filter sizes and structures. VGG uses a simple design to study deeper networks, without fully resolving optimization at very large depth. It is one CNN development branch, not the origin of every deep architecture.'),
 mechanism:p('Các khối tích chập 3×3 đi kèm phi tuyến và giảm kích thước không gian theo giai đoạn. Phiên bản VGG-16 và VGG-19 khác số tầng có trọng số. Đầu fully connected lớn góp phần đáng kể vào bộ nhớ tham số; chi phí này khác chi phí kích hoạt trong huấn luyện.','Blocks of 3×3 convolutions and nonlinearities reduce spatial size in stages. VGG-16 and VGG-19 differ in the number of weighted layers. Large fully connected heads contribute substantial parameter memory, which differs from activation memory during training.'),
 training:p('Bài báo học phân loại ImageNet và nghiên cứu cấu hình mạng sâu. Khi dùng làm backbone, phải ghi rõ tiền huấn luyện và cách fine-tune. So sánh chỉ số cần thống nhất độ phân giải, ngân sách và cách đánh giá, thay vì xem tên kiến trúc là toàn bộ thí nghiệm.','The paper trains ImageNet classifiers and studies deeper configurations. Backbone use should state pretraining and fine-tuning choices. Comparisons need consistent resolution, budgets, and evaluation; an architecture name is not a complete experiment.'),
 results:p('Kết quả và khả năng chuyển đặc trưng cho thấy giá trị của biểu diễn CNN sâu trong các tác vụ được xét. Tuy nhiên bộ nhớ và tính toán cao là hạn chế thực tế. Mạng sâu hơn không bảo đảm dễ học hơn; quá khớp và suy giảm tối ưu cần được phân biệt.','Results and feature-transfer experiments support deep CNN representations on the studied tasks. Memory and compute remain practical limitations. Greater depth does not guarantee easier learning; overfitting and optimization degradation must be distinguished.'),
 next:p('ResNet dùng baseline chịu ảnh hưởng của VGG để kiểm tra học phần dư. Hướng nghiên cứu minh họa là giữ độ sâu cố định rồi so sánh kết nối tắt, độ rộng và chuẩn hóa. Cần kiểm soát các yếu tố đồng thời thay đổi để hiểu nguồn gốc cải thiện.','ResNet uses a VGG-inspired baseline to investigate residual learning. An illustrative study fixes depth and compares shortcuts, width, and normalization. Control factors that change together to understand the source of improvements.')
});
model('resnet','ResNet',2015,'cnn-features',{
 insight:p('ResNet thay việc học ánh xạ trực tiếp bằng học phần dư quanh đường tắt: y = x + F(x). Cấu trúc này giúp tối ưu các mạng sâu trong thực nghiệm. Đường đồng nhất cho phép khối biểu diễn việc không thay đổi đầu vào; không có nghĩa mọi tầng đều học bằng không.','ResNet learns a residual around a shortcut, y = x + F(x), rather than only a direct mapping. This structure aids optimization of deep networks empirically. The identity path lets a block represent no change to its input; it does not mean every layer learns zero.'),
 origins:p('Nguồn gốc là ý tưởng học phần hiệu chỉnh và đường truyền đồng nhất. Trong bài gốc, baseline chịu ảnh hưởng thiết kế VGG. Mối liên hệ này có chứng cứ kiến trúc; không nên biến thành tuyên bố ResNet chỉ là VGG thêm một biểu tượng cộng.','Residual correction and identity paths are the foundations. The original baseline draws on VGG-style design. That architectural relationship is documented, but ResNet is not simply VGG with an addition symbol.'),
 gap:p('Bài báo tách suy giảm tối ưu khỏi quá khớp: mạng plain sâu hơn có thể có lỗi huấn luyện cao hơn. Thêm dữ liệu không trực tiếp giải thích vấn đề đó. Mục tiêu là tìm tham số hóa giúp mạng rất sâu có thể học, không bảo đảm toàn bộ lỗi tổng quát hóa biến mất.','The paper distinguishes optimization degradation from overfitting: a deeper plain network can have higher training error. More data does not directly explain that issue. The aim is a trainable parameterization, not elimination of every generalization error.'),
 mechanism:p('Khối residual cộng đầu ra nhánh học với shortcut. Khi số chiều thay đổi, có thể dùng phép chiếu phù hợp; không cộng tùy ý các tensor khác hình dạng. Các cấu hình bottleneck giảm chi phí cho mạng rất sâu. Đường tắt hỗ trợ truyền tín hiệu nhưng không phải bảo đảm toán học về tối ưu toàn cục.','A residual block adds a learned branch to a shortcut. Dimension changes need a suitable projection; arbitrary tensor shapes cannot be added. Bottleneck designs manage cost at greater depths. Shortcuts help signal flow but do not guarantee globally optimal training.'),
 training:p('Bài báo đánh giá trên ImageNet và CIFAR, cùng các tác vụ liên quan. Tái hiện cần xác định basic block hay bottleneck, số tầng, chuẩn hóa và lịch học. Một ablation có ý nghĩa giữ số tầng và giao thức cố định khi so sánh mạng plain với residual.','The paper evaluates ImageNet, CIFAR, and related tasks. Reproduction must specify basic versus bottleneck blocks, depth, normalization, and schedule. A meaningful ablation fixes depth and protocol when comparing plain and residual networks.'),
 results:p('Các thực nghiệm hỗ trợ khả năng huấn luyện mạng sâu hơn và hiệu quả trên benchmark được báo cáo. Điều đó không chứng minh tính bền vững trước mọi dịch chuyển phân phối. Năm 2015 là bản thảo đầu; bài hội nghị là CVPR 2016. Không trộn năm này với một ngày xuất bản giả định.','Experiments support training deeper networks and benchmark effectiveness. They do not establish robustness under every distribution shift. The initial preprint is from 2015 and the conference paper is CVPR 2016; neither is an invented publication date.'),
 next:p('Residual blocks xuất hiện trong nhiều mạng sinh, nhưng dùng cùng cấu trúc không đủ để chứng minh mọi ảnh hưởng lịch sử. Hãy đọc thiết kế backbone và trích dẫn của từng bài. Cơ hội nghiên cứu minh họa gồm cân bằng độ sâu, hiệu quả và độ bền trong cùng ngân sách.','Residual blocks appear in many generative architectures, but shared structure alone does not establish historical influence. Read each paper’s backbone and citations. Illustrative research opportunities balance depth, efficiency, and robustness under a common budget.')
});
model('vae','Variational Autoencoder',2013,'generative-objectives',{
 insight:p('VAE học mô hình sinh có biến ẩn cùng bộ suy luận xấp xỉ. Thay vì tối ưu trực tiếp posterior khó tính, phương pháp tối ưu cận dưới biến phân. Encoder dự đoán một phân phối, không chỉ một mã cố định; decoder ánh xạ mẫu ẩn thành phân phối dữ liệu.','A VAE learns a latent generative model together with approximate inference. It optimizes a variational lower bound instead of an intractable posterior directly. The encoder predicts a distribution rather than only a fixed code; the decoder maps latent samples to a data distribution.'),
 origins:p('Suy luận biến phân, mô hình xác suất và tối ưu ngẫu nhiên là nền tảng. Reparameterization tách nhiễu khỏi tham số phân phối để ước lượng gradient có thể dùng cho học. Ví dụ Gaussian thường dùng z = μ + σ·ε với ε lấy từ phân phối chuẩn.','Variational inference, probabilistic modeling, and stochastic optimization are its foundations. Reparameterization separates noise from distribution parameters so gradients can be estimated for learning. A Gaussian example uses z = μ + σ·ε with standard-normal ε.'),
 gap:p('Posterior thật của mô hình phi tuyến thường không giải tích được; cập nhật suy luận riêng từng điểm có thể đắt. Inference network dùng chung tham số để suy luận nhanh. Đổi lại, họ phân phối xấp xỉ và năng lực decoder có thể hạn chế nghiệm tìm được.','Nonlinear-model posteriors are often intractable, and per-example inference can be expensive. A shared inference network amortizes this work. Its approximate family and decoder capacity can constrain the solution.'),
 mechanism:p('Mục tiêu ELBO gồm kỳ vọng log likelihood trừ KL giữa posterior xấp xỉ và prior. Hạng tái tạo khuyến khích giải thích quan sát; KL điều hòa phân phối mã. Không nên gọi KL đơn giản là lỗi tái tạo, hoặc coi tối đa ELBO là tối đa likelihood chính xác.','The ELBO combines expected log likelihood minus KL divergence from approximate posterior to prior. Reconstruction explains observations; KL regularizes the codes. KL is not reconstruction error, and maximizing the bound is not exact likelihood maximization.'),
 training:p('Lấy minibatch, dự đoán tham số posterior, lấy mẫu bằng reparameterization rồi cập nhật encoder và decoder. Phân phối đầu ra phải phù hợp dữ liệu. Khi thử nghiệm nén ảnh, hãy xem cả chất lượng tái tạo và cấu trúc latent; một chỉ số không mô tả hết mô hình.','For a minibatch, predict posterior parameters, sample with reparameterization, and update encoder and decoder. Choose an observation distribution appropriate to the data. In image-compression exercises, examine reconstructions and latent structure rather than relying on one score.'),
 results:p('Bài báo minh họa học và suy luận hiệu quả cho các mô hình biến ẩn được xét. Chất lượng mẫu phụ thuộc likelihood, kiến trúc và cách tối ưu. Đây không phải bằng chứng rằng latent tự động tách được các yếu tố nhân quả hoặc giữ mọi chi tiết quan sát.','The paper demonstrates learning and inference in the studied latent-variable models. Sample quality depends on likelihood, architecture, and optimization. Latents do not automatically disentangle causal factors or preserve every observed detail.'),
 next:p('World Models dùng VAE để nén ảnh trước khi học động lực; latent diffusion kết hợp autoencoder với diffusion ở không gian nén. Đây là hai nhánh sử dụng biểu diễn ẩn cho mục tiêu khác nhau. Câu hỏi minh họa: nén bỏ thông tin nào cần thiết cho điều khiển hoặc sinh ảnh?','World Models uses a VAE to compress images before learning dynamics; latent diffusion combines an autoencoder with diffusion in compressed space. These are different uses of latent representation. An illustrative question asks which compressed-away information matters for control or generation.')
});
model('gan','GAN',2014,'generative-objectives',{
 insight:p('GAN học mô hình sinh thông qua trò chơi giữa generator và discriminator. Bộ phân biệt học phân biệt dữ liệu thật với mẫu sinh; generator học tạo mẫu làm việc phân biệt khó hơn. Đây là một nhánh mục tiêu khác VAE, không phải bước kế thừa được suy ra từ năm công bố.','GANs learn generation through a game between generator and discriminator. The discriminator separates real data from generated samples; the generator makes that discrimination harder. This objective is a different branch from VAEs, not an inheritance implied by publication year.'),
 origins:p('Nền tảng là ước lượng phân phối qua phân biệt và tối ưu trò chơi. Phân tích lý thuyết trong bài gốc dùng những giả định lý tưởng về năng lực và tối ưu. Không nên diễn giải kết quả lý tưởng thành bảo đảm hội tụ của mạng hữu hạn được huấn luyện thực tế.','Distribution estimation through discrimination and game optimization underpins GANs. The original theoretical analysis assumes ideal capacity and optimization. Its idealized result is not a convergence guarantee for finite networks trained in practice.'),
 gap:p('Một số mô hình sinh đòi hỏi suy luận latent hoặc likelihood khó xử lý. GAN tránh tính likelihood tường minh bằng phản hồi từ discriminator. Đổi lại, huấn luyện hai mô hình tương tác gây khó đánh giá và cân bằng; không có ELBO để theo dõi như VAE.','Some generators require difficult latent inference or likelihood calculation. GANs use discriminator feedback without an explicit likelihood. Interacting learners introduce balancing and evaluation challenges; there is no VAE-style ELBO to monitor.'),
 mechanism:p('Generator nhận nhiễu rồi sinh mẫu; discriminator xuất mức tin là mẫu thật. Cập nhật luân phiên theo mục tiêu đối kháng. Bài báo bàn cả mục tiêu thay thế thực dụng cho generator khi gradient ban đầu yếu. Chất lượng discriminator và lịch cập nhật ảnh hưởng tín hiệu học.','The generator maps noise to samples and the discriminator estimates realness. Training alternates adversarial updates. The paper also discusses a practical alternative generator objective when early gradients are weak. Discriminator quality and update schedules shape the learning signal.'),
 training:p('Dùng dữ liệu thật và nhiễu lấy mẫu độc lập, cập nhật hai mạng có kiểm soát. Không đánh giá bằng vài ảnh được chọn đẹp nhất. Một bài kiểm tra hữu ích báo cáo độ đa dạng, chất lượng và cách chọn mẫu; đây là khuyến nghị đánh giá chứ không phải kết quả bổ sung.','Use real examples and independently sampled noise, with controlled updates to both networks. Do not evaluate only cherry-picked attractive images. Report diversity, quality, and sample selection; this is evaluation guidance, not an additional paper result.'),
 results:p('Thực nghiệm cho thấy khung đối kháng có thể học sinh dữ liệu trong các thiết lập được khảo sát. Mẫu đẹp không chứng minh bao phủ đầy đủ phân phối. Mất ổn định và bỏ sót mode là những vấn đề cần theo dõi khi dùng họ phương pháp này, không được che bằng chỉ một loss.','Experiments show adversarial generation in the investigated settings. Attractive samples do not establish distribution coverage. Instability and missing modes are issues to monitor in this family, not problems hidden by reporting a single loss.'),
 next:p('Diffusion dùng mục tiêu khử nhiễu thay vì trò chơi generator–discriminator gốc. So sánh chúng nên kiểm soát dữ liệu và chi phí lấy mẫu. Không nối GAN sang DDPM như một quan hệ cha–con chỉ vì cả hai tạo ảnh; cần bằng chứng riêng cho một ảnh hưởng phương pháp cụ thể.','Diffusion uses denoising rather than the original generator–discriminator game. Compare methods with controlled data and sampling costs. Do not draw a parent–child edge from GAN to DDPM merely because both generate images; a specific influence needs separate evidence.')
});
model('ddpm','DDPM',2020,'generative-objectives',{
 insight:p('DDPM học đảo ngược một quá trình thêm nhiễu có kiểm soát. Mạng được huấn luyện nhận trạng thái nhiễu và mức thời gian để hỗ trợ khử nhiễu từng bước. Quá trình lấy mẫu bắt đầu từ nhiễu; không phải truy hồi trực tiếp một ảnh huấn luyện bằng chỉ số.','DDPM learns to reverse controlled corruption. A network receives a noisy state and time level to support stepwise denoising. Sampling starts from noise; it is not direct retrieval of a training image by index.'),
 origins:p('Bài báo nối mô hình diffusion xác suất với denoising score matching. Quá trình thuận và ngược có diễn giải biến phân, nhưng loss đơn giản hóa được dùng thực tế không đồng nhất mọi trọng số của bound gốc. Khử nhiễu là nhiệm vụ học chứ không chỉ là bộ lọc cố định.','The paper connects probabilistic diffusion with denoising score matching. Forward and reverse processes have a variational interpretation, while the practical simplified loss does not preserve all original bound weights. Denoising is learned, not a fixed image filter.'),
 gap:p('Mô hình sinh cần cân bằng chất lượng, tính ổn định và khả năng đánh giá. DDPM nghiên cứu một lựa chọn dùng nhiều bước sinh có xác suất. Đây không phải mô hình diffusion đầu tiên; đóng góp nằm trong cách huấn luyện và chứng cứ chất lượng của hệ thống được đề xuất.','Generative modeling balances quality, stability, and evaluation. DDPM studies a probabilistic multistep alternative. It is not the first diffusion model; its training formulation and evidence for the proposed system matter.'),
 mechanism:p('Chọn timestep, thêm nhiễu Gaussian theo lịch, rồi học dự đoán thành phần nhiễu. Khi sinh, dùng dự đoán để tham số hóa các chuyển tiếp ngược. Kiến trúc có điều kiện thời gian và các khối residual. Tín hiệu thời gian giúp cùng mạng xử lý nhiều mức nhiễu.','Sample a timestep, add scheduled Gaussian noise, and train a noise predictor. During generation, its estimates parameterize reverse transitions. The time-conditioned architecture includes residual blocks; time information lets one network handle multiple corruption levels.'),
 training:p('Ví dụ ảnh dùng mẫu dữ liệu thật, timestep và nhiễu ngẫu nhiên trong mỗi cập nhật. Tách rõ số bước huấn luyện với số bước lấy mẫu. Thử nghiệm thay lịch nhiễu cần cùng dữ liệu và ngân sách; không gán chỉ số của các sampler mới hơn cho bài DDPM gốc.','Image training samples data, timesteps, and noise at each update. Distinguish optimization steps from sampling steps. Noise-schedule experiments need controlled data and budgets; do not attribute later sampler metrics to original DDPM.'),
 results:p('Bài báo báo cáo tổng hợp ảnh chất lượng cao trên các benchmark được nghiên cứu. Quá trình sinh nhiều bước làm tăng chi phí suy luận. Kết quả ảnh không tự chứng minh hiểu biết vật lý hoặc độ tin cậy trong ứng dụng y tế; các thuộc tính đó cần kiểm tra riêng.','The paper reports high-quality synthesis on its studied benchmarks. Multistep generation increases inference cost. Image results do not establish physical understanding or medical reliability; those properties require separate evaluation.'),
 next:p('Latent diffusion chuyển quá trình khử nhiễu sang biểu diễn nén để giảm chi phí không gian ảnh lớn. Hướng nghiên cứu minh họa là cân bằng độ nén, độ trung thực và tốc độ. Timeline phân biệt mở rộng phương pháp có nguồn với các mô hình chỉ cùng thời kỳ.','Latent diffusion moves denoising into compressed representations to reduce high-resolution costs. An illustrative research direction balances compression, fidelity, and speed. The timeline separates sourced extensions from models that simply appeared in nearby years.')
});
model('ldm','Latent Diffusion',2021,'generative-objectives',{
 insight:p('Latent diffusion tách nén cảm nhận khỏi mô hình hóa sinh: autoencoder học biểu diễn ảnh, diffusion học phân phối trong không gian đó. Cách chia này tránh thực hiện toàn bộ chuỗi khử nhiễu trên pixel độ phân giải cao. Năm 2021 là bản thảo đầu, không phải năm hội nghị CVPR 2022.','Latent diffusion separates perceptual compression from generation: an autoencoder represents images and diffusion models that space. It avoids running the entire denoising chain at high pixel resolution. Here 2021 is the initial preprint, not the CVPR 2022 conference year.'),
 origins:p('Nền tảng kết hợp autoencoding, regularization của latent và diffusion. Cross-attention hỗ trợ điều kiện như văn bản trong kiến trúc được đề xuất. Không nên đồng nhất mọi autoencoder của bài với VAE gốc: bài khảo sát lựa chọn regularization khác nhau.','It combines autoencoding, latent regularization, and diffusion. Cross-attention supports conditions such as text in the proposed architecture. Not every first-stage autoencoder is identical to original VAE; the paper studies different regularization choices.'),
 gap:p('Diffusion trên pixel lớn tốn bộ nhớ và tính toán; nén quá mạnh lại làm mất chi tiết. Mục tiêu là chọn không gian nén giữ thông tin cảm nhận hữu ích. Hai giai đoạn tạo thêm giả định: những gì encoder bỏ đi không thể được khôi phục một cách được bảo đảm.','High-resolution pixel diffusion is expensive, while excessive compression loses detail. The aim is a space that retains useful perceptual information. The two stages introduce an assumption: information discarded by the encoder cannot be guaranteed to return.'),
 mechanism:p('Huấn luyện autoencoder trước; sau đó học khử nhiễu trên mã latent và giải mã mẫu sinh. Điều kiện đi vào denoiser qua cơ chế phù hợp như cross-attention. Quan hệ với DDPM là mở rộng diffusion; quan hệ với autoencoding là chuyển giao biểu diễn, không phải thứ tự năm tự tạo ra.','Train an autoencoder, learn latent denoising, and decode generated codes. Conditions enter the denoiser through mechanisms such as cross-attention. Its relation to DDPM is a diffusion extension; autoencoding supplies representation rather than a lineage inferred from dates.'),
 training:p('Dữ liệu và điều kiện phụ thuộc tác vụ: sinh vô điều kiện, văn bản–ảnh hoặc khôi phục ảnh. Chọn hệ số nén và đánh giá cả first stage lẫn hệ sinh. Một cấu hình cụ thể cần ghi rõ encoder, regularization và dữ liệu; tên latent diffusion không xác định toàn bộ quy trình.','Data and conditions depend on the task: unconditional synthesis, text-to-image, or restoration. Evaluate the compression stage as well as generation. Specify the encoder, regularization, and data; the label latent diffusion does not define a complete pipeline.'),
 results:p('Bài báo đưa ra đánh giá chất lượng và chi phí trên nhiều tác vụ ảnh. Không có một mức tăng tốc áp dụng cho mọi độ phân giải hay thiết bị. Sai lệch dữ liệu, lỗi điều kiện và giới hạn nén vẫn cần đánh giá; ảnh thuyết phục không bảo đảm đúng sự thật.','The paper evaluates quality and cost across image tasks. No single speedup applies to every resolution or device. Data biases, conditioning errors, and compression limits still need evaluation; convincing images do not guarantee truthfulness.'),
 next:p('So sánh latent cho sinh ảnh với latent cho điều khiển giúp đặt câu hỏi về thông tin cần giữ. Đây là liên hệ phân tích, không phải tuyên bố World Models là tổ tiên trực tiếp của latent diffusion. Thử nghiệm cần đo nhiệm vụ đích thay vì chỉ loss tái tạo.','Comparing generation latents with control latents raises questions about information retention. This is an analytical connection, not a claim that World Models directly precedes latent diffusion. Evaluate the target task rather than reconstruction loss alone.')
});
model('world','World Models',2018,'latent-control',{
 insight:p('World Models tách nhận thức, trí nhớ và bộ điều khiển. Một mô hình sinh học biểu diễn nén và động lực thời gian; bộ điều khiển nhỏ sử dụng trạng thái đó để hành động. Mô hình học môi trường từ dữ liệu, không được cung cấp mọi định luật vật lý hay trạng thái thật.','World Models separates perception, memory, and a controller. A generative model learns compressed representations and temporal dynamics; a small controller acts on that state. The model learns from data, without receiving every physical law or true environment state.'),
 origins:p('Bài báo kết hợp VAE cho ảnh với mạng hồi tiếp dự đoán phân phối latent tương lai. Đây là chuyển giao cụ thể từ mô hình sinh sang điều khiển. Dùng từ tưởng tượng không có nghĩa mô hình có ý thức; đó là rollout trong môi trường học được.','The paper combines a visual VAE with recurrent prediction of future latent distributions. This is a concrete transfer from generation to control. Imagination refers to rollouts in a learned environment, not consciousness.'),
 gap:p('Học chính sách trực tiếp trên ảnh khiến biểu diễn và thời gian khó xử lý. Nén quan sát giúp bộ điều khiển nhỏ hơn. Tuy nhiên dữ liệu khám phá ban đầu có thể không bao phủ các tình huống chính sách sẽ gặp, gây sai lệch khi chuyển từ mô hình sang môi trường thật.','Learning policies directly from images complicates representation and temporal reasoning. Compression simplifies the controller. Initial exploratory data may miss states later visited by the policy, causing learned-to-real environment mismatch.'),
 mechanism:p('V mã hóa ảnh; M dự đoán động lực latent bằng MDN-RNN; C chọn hành động từ thông tin nén và bộ nhớ. Trong ví dụ học trong mơ, bộ điều khiển được tối ưu trong môi trường mô phỏng học được. Nhiễu lấy mẫu ảnh hưởng khả năng khai thác lỗi mô hình.','V encodes images, M predicts latent dynamics with an MDN-RNN, and C acts using compressed state and memory. In dream-based examples the controller is optimized inside a learned simulator. Sampling noise affects how easily it exploits model errors.'),
 training:p('Thu thập trải nghiệm để học V và M rồi tối ưu C bằng chiến lược tiến hóa trong các thí nghiệm gốc. Không thay nhầm thành actor–critic của Dreamer. Khi tái hiện, báo cáo cách thu thập dữ liệu và việc học trong môi trường thật hay mô phỏng.','Collect experience to learn V and M, then optimize C with evolutionary strategies in the original experiments. Do not substitute Dreamer’s actor–critic and call it the original. State how data are collected and whether behavior learning uses the real environment or model.'),
 results:p('Bài báo và demo thể hiện điều khiển trong các môi trường chọn lọc như CarRacing và VizDoom. Không suy ra an toàn robot thật hoặc suy luận nhân quả tổng quát. Lỗi động lực và thiếu phủ trạng thái có thể tích lũy qua rollout dài.','The paper and demonstrations show control in selected settings including CarRacing and VizDoom. They do not establish real-robot safety or general causal reasoning. Dynamics errors and poor state coverage can accumulate through longer rollouts.'),
 next:p('PlaNet và Dreamer dùng những thiết kế trạng thái và tối ưu khác để học từ pixel. Chúng cùng nhánh nghiên cứu nhưng mỗi cạnh kế thừa phải có chứng cứ riêng. Cơ hội nghiên cứu minh họa là phát hiện khi rollout ra khỏi vùng dữ liệu đáng tin và thu thập thêm trải nghiệm.','PlaNet and Dreamer use different state and optimization designs for pixel-based learning. A shared research area does not establish every lineage edge. An illustrative opportunity is detecting rollouts outside reliable data coverage and collecting more experience.')
});
model('planet','PlaNet',2018,'latent-control',{
 insight:p('PlaNet học động lực trong không gian latent để lập kế hoạch từ ảnh. Thay vì dự đoán pixel ở mỗi bước tối ưu hành động, agent tìm các chuỗi hành động hứa hẹn trong mô hình nén. Năm 2018 là bản thảo; phiên bản hội nghị là ICML 2019.','PlaNet learns latent dynamics for planning from images. Instead of generating pixels at every action-search step, the agent evaluates promising action sequences in a compressed model. Here 2018 is the preprint year; the conference version is ICML 2019.'),
 origins:p('Nền tảng là state-space modeling, suy luận biến phân và model predictive control. Recurrent state-space model kết hợp thành phần tất định với trạng thái ngẫu nhiên. Thành phần nhớ và bất định phục vụ các vai trò khác nhau; không nên gộp chúng thành một vector không có cấu trúc.','State-space modeling, variational inference, and model predictive control provide the foundations. A recurrent state-space model combines deterministic and stochastic state. Memory and uncertainty serve different roles rather than forming an unstructured vector.'),
 gap:p('Lập kế hoạch trên pixel tốn chi phí và mô hình một bước có thể sai khi rollout. PlaNet nghiên cứu biểu diễn latent đủ để dự đoán phần thưởng và ra quyết định. Khả năng tái tạo ảnh không tự bảo đảm mô hình giữ mọi thông tin cần cho điều khiển.','Pixel-space planning is costly and one-step models may drift during rollouts. PlaNet studies latent states useful for reward prediction and decisions. Accurate reconstruction alone does not guarantee retention of every control-relevant feature.'),
 mechanism:p('Posterior dùng quan sát để suy ra trạng thái; prior dự đoán trạng thái tương lai theo hành động. Planner dùng tìm kiếm chuỗi hành động trong latent rồi thực hiện hành động đầu và lập kế hoạch lại. Latent overshooting thêm ràng buộc nhiều bước; nó không xóa hoàn toàn lỗi mô hình.','The posterior infers states from observations; the prior predicts future states under actions. A planner searches latent action sequences, executes the first action, and replans. Latent overshooting adds multistep constraints without eliminating all model error.'),
 training:p('Agent thu thập các chuỗi ảnh, hành động và phần thưởng, học mô hình rồi lặp lại thu thập. Thực nghiệm cần xác định action repeat, horizon và ngân sách tương tác. Đánh giá riêng chất lượng mô hình và thành công điều khiển để tránh dùng loss dự đoán thay thế hoàn toàn điểm tác vụ.','The agent collects image, action, and reward sequences, fits the model, and repeats collection. Specify action repeat, horizon, and interaction budget. Evaluate modeling and control separately rather than treating prediction loss as task success.'),
 results:p('Các tác vụ điều khiển từ pixel cho thấy hiệu quả của lập kế hoạch trong latent ở thiết lập được xét. Tìm kiếm hành động vẫn cần tính toán tại thời điểm quyết định. Nếu mô hình lệch hoặc horizon quá ngắn, planner có thể chọn hành động không tốt dù dự đoán một bước đẹp.','Pixel-control tasks demonstrate latent planning in the evaluated setting. Action search still costs computation at decision time. Model bias or a short horizon can lead to poor decisions despite plausible one-step predictions.'),
 next:p('Dreamer chuyển từ tìm kiếm hành động trực tuyến sang học hành vi qua rollout tưởng tượng. Một so sánh hữu ích đo cả số tương tác và chi phí suy luận, không chỉ điểm cuối. Các nghiên cứu về uncertainty hoặc planning dài hơn là cơ hội, không phải tính năng đã được chứng minh ở đây.','Dreamer shifts from online action search to behavior learning through imagined rollouts. Compare interaction count and decision-time cost, not only final scores. Uncertainty handling and longer planning are research opportunities rather than established features here.')
});
model('dreamer','Dreamer',2019,'latent-control',{
 insight:p('Dreamer học actor và value trong tưởng tượng của mô hình thế giới. Hành vi được cải thiện bằng gradient qua động lực latent thay vì tìm kiếm một chuỗi hành động mới tại mỗi quyết định như PlaNet. Năm 2019 chỉ bản thảo đầu; bài báo xuất hiện ở ICLR 2020.','Dreamer learns an actor and value model in the world model’s imagination. Behavior improves through gradients in latent dynamics rather than a fresh action-sequence search at every decision as in PlaNet. The first preprint is 2019; the paper appeared at ICLR 2020.'),
 origins:p('Mô hình trạng thái hồi tiếp của nhánh PlaNet kết hợp với học giá trị và tối ưu chính sách. Gradient đi qua những rollout latent có thể vi phân. Đây là cơ chế tính toán, không có nghĩa mô hình dự đoán hoàn hảo hay chính sách luôn tìm được hành vi tối ưu.','PlaNet-style recurrent states combine with value learning and policy optimization. Gradients pass through differentiable latent rollouts. This computational mechanism implies neither perfect predictions nor an always-optimal policy.'),
 gap:p('Planner trực tuyến có thể tốn thời gian và bị giới hạn horizon. Học một chính sách có thể tái sử dụng giúp giảm nhu cầu tìm kiếm khi hành động. Vấn đề mới là chất lượng imagined returns: tối ưu mạnh trên mô hình sai có thể khiến hành vi khai thác lỗi.','Online planners can be expensive and horizon-limited. A reusable policy reduces search at action time. The challenge becomes the quality of imagined returns: strong optimization against a flawed model can exploit its errors.'),
 mechanism:p('Học world model từ replay; khởi tạo trạng thái từ dữ liệu thật; rollout theo actor; dùng dự đoán phần thưởng và value bootstrap để cập nhật hành vi. Value hỗ trợ nhìn xa hơn rollout ngắn. Actor–critic và mô hình có các vai trò khác nhau, không nên gọi cả hệ là một bộ dự đoán video.','Learn a world model from replay, initialize states from real experience, roll out the actor, and use predicted rewards plus value bootstrapping to improve behavior. Value extends the effective horizon. The actor, critic, and model have different roles; the system is not merely a video predictor.'),
 training:p('Quy trình xen kẽ thu thập tương tác và cập nhật từ replay. So sánh phải thống nhất dữ liệu môi trường và ngân sách tính toán. Kiểm tra rollout dài dần là một phân tích hữu ích để thấy trade-off giữa nhìn xa và tích lũy sai số, chứ không phải kết quả được thêm vào paper.','Alternate interaction collection and replay-based updates. Comparisons should align environment data and compute. Increasing rollout length is an informative analysis of foresight versus accumulated error, not an additional result inserted into the paper.'),
 results:p('Bài báo đánh giá nhiều tác vụ điều khiển từ pixel và các lựa chọn biểu diễn. Kết quả hỗ trợ học hành vi trong latent nhưng không bảo đảm chuyển giao sang robot vật lý hoặc môi trường ngoài phân phối. Phần thưởng, biểu diễn và độ chính xác của động lực vẫn là các giả định quan trọng.','The paper evaluates pixel-control tasks and representation choices. Results support latent behavior learning without guaranteeing transfer to physical robots or out-of-distribution environments. Rewards, representations, and dynamics accuracy remain important assumptions.'),
 next:p('DreamerV3 thuộc họ này nhưng có các thay đổi lớn và đi qua DreamerV2, không được vẽ như bản vá nhỏ trực tiếp. UI dùng cạnh mở rộng cấp họ và ghi rõ mốc bị lược. Hướng nghiên cứu là kiểm tra độ bền nhiều miền mà không điều chỉnh siêu tham số theo từng tác vụ.','DreamerV3 belongs to this family but follows substantial changes, including intervening DreamerV2. The UI uses a family-level extension edge and explicitly notes that omission. A research direction is cross-domain robustness without per-task hyperparameter tuning.')
});
model('dreamerv3','DreamerV3',2023,'latent-control',{
 insight:p('DreamerV3 nhằm học nhiều miền điều khiển với một cấu hình thuật toán. Nó giữ học hành vi bằng tưởng tượng nhưng chuẩn hóa và cân bằng các thành phần để giảm nhạy với thang đo tác vụ. Mốc 2023 là bản thảo đầu; trang tác giả có phiên bản công bố sau đó.','DreamerV3 targets many control domains with one algorithm configuration. It retains imagined behavior learning while normalizing and balancing components to reduce task-scale sensitivity. The year 2023 is the initial preprint; the authors also link a later published version.'),
 origins:p('Nguồn gốc là họ Dreamer: mô hình thế giới latent, actor–critic và replay. Nhánh này có DreamerV2 nằm giữa các mốc được chọn. Biến đổi symlog và các cơ chế ổn định là quyết định tối ưu hóa cụ thể, không phải khẳng định hiểu mọi quy luật vật lý.','Its origins are the Dreamer family: latent world models, actor–critic learning, and replay. DreamerV2 lies between the selected milestones. Symlog transformations and stabilization are concrete optimization choices, not claims of understanding all physical laws.'),
 gap:p('Thuật toán RL thường cần điều chỉnh theo thang phần thưởng, quan sát và độ khó khám phá. Tính nhất quán cấu hình được nghiên cứu trên các miền đa dạng. Một cấu hình trong bộ benchmark không đồng nghĩa không cần thiết kế dữ liệu, tài nguyên hay mục tiêu cho ứng dụng mới.','RL algorithms often require adjustments to reward scale, observations, and exploration difficulty. Configuration robustness is studied across diverse domains. A shared benchmark configuration does not remove data, resource, and objective design in a new application.'),
 mechanism:p('World model học trạng thái latent từ replay; actor và critic học từ rollout tưởng tượng. Bài bản thảo mô tả các biến đổi mục tiêu, regularization và chuẩn hóa để ổn định học. Muốn tái hiện cần dùng đúng phiên bản mã và phụ lục, không ghép các mặc định giữa Dreamer gốc và V3.','The world model learns latent states from replay; actor and critic learn from imagined trajectories. The preprint describes target transformations, regularization, and normalization for stability. Reproduction needs matching code and appendix versions rather than mixing original-Dreamer and V3 defaults.'),
 training:p('Dữ liệu gồm quan sát, hành động, phần thưởng và tín hiệu kết thúc từ tương tác. Huấn luyện lặp lại trên replay và đánh giá nhiều seed. Bài kiểm tra đề xuất là giữ cấu hình cố định khi đổi thang phần thưởng hoặc miền; đây là cách kiểm tra robustness chứ không phải số liệu mới.','Data include observations, actions, rewards, and termination signals from interaction. Training reuses replay and evaluation should consider multiple seeds. A proposed check keeps the configuration fixed across reward scales or domains; it is a robustness test, not a new reported metric.'),
 results:p('Bản thảo báo cáo kết quả đa miền và các ablation về lựa chọn ổn định. Không trình bày điểm số ở đây để tránh ghép phiên bản và giao thức khác nhau. Thành công benchmark không bảo đảm an toàn triển khai, khả năng nhân quả hoặc tổng quát hóa tới mọi môi trường chưa thấy.','The preprint reports cross-domain results and stabilization ablations. This prototype omits scores to avoid mixing versions and protocols. Benchmark success does not establish deployment safety, causal reasoning, or generalization to every unseen environment.'),
 next:p('Cơ hội phân tích là phân biệt độ bền tối ưu hóa với độ đúng của world model. Có thể khảo sát lỗi rollout dưới thay đổi động lực, rồi kiểm tra chính sách trong môi trường thật. Đây là câu hỏi học thuật minh họa, không phải ý tưởng nghiên cứu riêng được lưu trong Atlas.','An analytical opportunity separates optimization robustness from world-model correctness. Study rollout error under changed dynamics, then test policies in the actual environment. This is a public illustrative question, not a private research idea stored in Atlas.')
});
// Illustrative reasoning exercises, not newly reported experiments or private research ideas.
const walkthrough={
 lenet:p('Ví dụ diễn giải: hai chữ số cùng có nét dọc nhưng khác một vòng khép kín. Tầng đầu có thể đáp ứng với dấu nét cục bộ; tầng sau kết hợp bằng chứng theo vùng để phân biệt chúng. Dịch ảnh vài pixel giúp kiểm tra giới hạn của chia sẻ trọng số và giảm mẫu. Nếu ảnh bị xoay mạnh, biểu diễn đã học có thể không còn phù hợp. Hãy phân tích các ca sai thay vì chỉ một tỷ lệ chính xác; thí nghiệm này minh họa cách đặt câu hỏi, không khẳng định neuron cụ thể của paper mang nghĩa con người đặt tên.','Illustrative reasoning: two digits share a vertical stroke but differ in a closed loop. Early layers can respond to local patterns; later layers combine spatial evidence to distinguish them. Shift an image by a few pixels to examine the limits of sharing and subsampling. Strong rotation may change the learned representation substantially. Inspect errors rather than only aggregate accuracy. This exercise illustrates a question to test; it does not assert that a particular neuron in the paper has the human-interpretable meaning assigned here.'),
 alexnet:p('Ví dụ diễn giải: ảnh cùng lớp có nền, vị trí và độ sáng khác nhau. Tăng cường dữ liệu tạo biến thiên có chủ đích trong tập huấn luyện; nhãn vẫn phải phù hợp sau biến đổi. So sánh lỗi train và validation giúp phân biệt thiếu khả năng khớp với quá khớp. Dropout chỉ dùng theo chế độ huấn luyện thích hợp, không tùy ý tắt neuron khi chấm điểm. Việc thay đổi đồng thời độ rộng, dữ liệu và GPU làm so sánh khó diễn giải; cần ghi rõ yếu tố thay đổi khi rút ra kết luận.','Illustrative reasoning: images of one class vary in background, position, and lighting. Augmentation introduces controlled training variation, but labels must remain valid after transformation. Training and validation errors help distinguish underfitting from overfitting. Dropout follows its training/evaluation convention rather than arbitrarily dropping neurons while scoring. Changing width, data, and hardware together complicates interpretation. Record which factors vary before attributing the outcome to a single architectural choice; the paper’s complete system is more informative than the network name alone.'),
 vgg:p('Ví dụ diễn giải: xếp nhiều bộ lọc nhỏ tăng số lần biến đổi phi tuyến trước khi quyết định nhãn. Điều này thay đổi cả năng lực biểu diễn và quá trình tối ưu, không chỉ vùng tiếp nhận. Để đánh giá một backbone, có thể cố định bộ phân loại mới rồi so sánh đặc trưng đã tiền huấn luyện với fine-tuning. Kết quả còn phụ thuộc miền và lượng dữ liệu mới. Một kiểm tra có kiểm soát không được thay đồng thời độ phân giải đầu vào, augmentation và lịch học rồi quy toàn bộ khác biệt cho chiều sâu.','Illustrative reasoning: stacking small filters increases the number of nonlinear transformations before classification. It changes representation and optimization, not only receptive field size. To study a backbone, compare a fixed classifier on pretrained features with fine-tuning, keeping the downstream split unchanged. Outcomes depend on domain and available data. A controlled depth study should not simultaneously change input resolution, augmentation, and schedule, then attribute all differences to depth. Memory measurement should also separate stored weights from training activations and optimizer state.'),
 resnet:p('Ví dụ diễn giải: nếu một khối mới chưa cần chỉnh biểu diễn, nhánh residual có thể học một hiệu chỉnh nhỏ trong khi shortcut duy trì đường truyền. Khi cần đổi số kênh hoặc độ phân giải, phép cộng đòi hỏi hai nhánh tương thích; kiểm tra hình dạng tensor là bước triển khai thiết yếu. Theo dõi lỗi train của plain và residual ở cùng độ sâu giúp kiểm tra đúng vấn đề suy giảm tối ưu. Nếu validation kém hơn dù train tốt, cần phân tích tổng quát hóa thay vì nói đường tắt đã thất bại theo cùng nghĩa.','Illustrative reasoning: when a new block needs little representational change, its residual branch can learn a small correction while the shortcut preserves a path. Channel or resolution changes require compatible branch shapes before addition; tensor-shape checks are essential in implementation. Compare training error for plain and residual networks at the same depth to examine optimization degradation. If validation worsens despite good training fit, investigate generalization rather than describing it as the same optimization problem. Residual learning is a structural choice, not a replacement for careful evaluation.'),
 vae:p('Ví dụ diễn giải: encoder biến một ảnh thành trung bình và độ lệch chuẩn của mã Gaussian. Lấy nhiễu ε rồi tính z làm quá trình lấy mẫu có đường gradient theo các tham số đó. Decoder được chấm bằng phân phối quan sát đã chọn. Để sinh ảnh mới không cần encoder của một ảnh thật: lấy z từ prior rồi giải mã. So sánh hai đường đi này giúp phân biệt tái tạo với sinh mới; ảnh tái tạo tốt không tự bảo đảm mẫu từ prior cũng tốt hay latent có ý nghĩa nhân quả.','Illustrative reasoning: an encoder maps an image to Gaussian-code means and scales. Sampling noise ε and computing z provides a gradient path through those parameters. The decoder is scored under a chosen observation distribution. New generation need not encode a real image: sample z from the prior and decode it. Comparing these paths distinguishes reconstruction from generation. Good reconstructions alone do not establish good prior samples or causally meaningful latents. Inspect both paths when interpreting what the representation has learned.'),
 gan:p('Ví dụ diễn giải: khi discriminator dễ nhận ra mẫu giả, cần xem generator có nhận gradient hữu ích hay không, thay vì chỉ đọc loss thấp của discriminator như dấu hiệu cả hệ tốt. Một generator sinh một vài mẫu lặp lại có thể trông thuyết phục nhưng không đa dạng. Quan sát một tập nhiễu cố định qua huấn luyện giúp so sánh tiến trình, song cũng cần mẫu độc lập để đánh giá cuối. Các bước này là hướng dẫn đọc thí nghiệm, không gán một mức chất lượng hoặc độ bao phủ mới cho GAN gốc.','Illustrative reasoning: when the discriminator easily identifies generated samples, inspect whether the generator receives useful gradients. A low discriminator loss does not mean the entire system works well. A generator repeating a few convincing outputs can still lack diversity. Fixed noise across training helps inspect progress, but independent samples are also needed for final evaluation. These are ways to interpret an experiment, not new quality or coverage measurements for original GAN. Compare the training objective with what the chosen evaluation actually measures.'),
 ddpm:p('Ví dụ diễn giải: cùng một ảnh có thể bị làm nhiễu nhẹ hoặc gần như mất hoàn toàn tín hiệu. Đầu vào thời gian cho biết mạng đang giải bài toán ở mức nào. Ở huấn luyện, ta biết nhiễu đã thêm để tạo mục tiêu; ở lấy mẫu, chỉ có trạng thái hiện tại và dự đoán của mạng. Phân biệt hai chế độ tránh hiểu nhầm rằng mô hình được xem đáp án thật trong khi sinh. Một ablation sampler phải ghi số bước và chi phí, không so sánh ảnh đẹp mà bỏ qua thời gian suy luận.','Illustrative reasoning: the same image can be lightly corrupted or almost completely obscured. Time conditioning identifies which denoising problem the network faces. During training, added noise is known and supplies a target; during sampling, only the current state and network prediction are available. Separating these modes avoids the misconception that generation sees the correct target image. Sampler comparisons should state step count and computational cost rather than judging attractive outputs without considering inference time or differences in protocol.'),
 ldm:p('Ví dụ diễn giải: nếu encoder làm mất một chữ nhỏ trên ảnh, diffusion latent không được bảo đảm tái tạo đúng chữ đó. Nó có thể tạo chi tiết hợp thị giác nhưng sai nội dung. Vì vậy cần kiểm tra riêng lỗi autoencoder và lỗi điều kiện sinh. Với văn bản điều kiện, chất lượng ảnh và mức phù hợp prompt là hai câu hỏi khác nhau. Thử nhiều độ nén trên cùng thiết lập giúp nghiên cứu trade-off; đây là thiết kế phép kiểm tra, không tuyên bố một độ nén luôn tối ưu cho mọi dữ liệu.','Illustrative reasoning: if compression removes small text in an image, latent diffusion cannot guarantee recovery of the correct letters. It may generate plausible but incorrect detail. Inspect autoencoder error separately from generation and conditioning error. With text conditions, image quality and prompt alignment are different questions. Comparing compression levels under one protocol investigates the trade-off rather than proving one compression factor optimal for every dataset. This distinction matters when moving from visual synthesis to applications requiring exact content.'),
 world:p('Ví dụ diễn giải: một agent thấy ảnh xe và đường nhưng không biết trạng thái vật lý thật. V rút gọn ảnh; M dùng lịch sử và hành động để dự đoán latent tiếp theo; C chọn hành động. Nếu M bỏ qua một chướng ngại hiếm, chính sách trong mơ có thể tận dụng lỗi đó. Kiểm tra trong môi trường gốc là thiết yếu sau tối ưu trong mô hình. Quan sát rollout đẹp không đủ để đánh giá điều khiển: cần xem hành động, phần thưởng và các trạng thái thất bại.','Illustrative reasoning: an agent observes a car and road without receiving the true physical state. V compresses the image; M uses history and actions to predict future latents; C selects an action. If M misses a rare obstacle, a dream-trained policy may exploit that error. Evaluation in the original environment remains essential after model-based optimization. Plausible rollouts alone do not evaluate control: examine actions, rewards, and failure states. This separates visual modeling quality from whether the learned simulator supports useful decisions.'),
 planet:p('Ví dụ diễn giải: planner thử các chuỗi hành động trong mô hình rồi chọn chuỗi dự đoán có tổng phần thưởng tốt. Nó chỉ thực hiện hành động đầu, quan sát lại và lập kế hoạch mới. Phản hồi này khác một rollout mở cố định tới cuối. Trạng thái stochastic hỗ trợ biểu diễn bất định, nhưng không tự bảo đảm planner biết mọi tình huống ngoài phân phối. Khi horizon dài hơn, lợi ích nhìn xa phải được cân với sai số động lực và chi phí tìm kiếm; đo cả ba thay vì chỉ điểm tác vụ.','Illustrative reasoning: the planner evaluates action sequences in the model and selects a promising predicted return. It executes only the first action, observes again, and replans. This feedback differs from committing to one open-loop sequence. Stochastic state supports uncertainty representation without guaranteeing awareness of every out-of-distribution event. A longer horizon trades foresight against dynamics error and search cost. Measure all three rather than treating task score as a full explanation of how the planning system behaves.'),
 dreamer:p('Ví dụ diễn giải: một trạng thái replay tạo điểm bắt đầu cho nhiều bước tưởng tượng. Actor chọn hành động; mô hình dự đoán trạng thái và phần thưởng; critic ước lượng phần còn lại sau rollout. Giá trị cuối giúp mục tiêu nhìn xa hơn số bước mô phỏng trực tiếp. Tuy nhiên critic cũng học từ thông tin hữu hạn, nên bootstrap không phải đáp án thật. So sánh với planner cần phân biệt chi phí học chính sách trước và chi phí hành động sau; hành động nhanh không có nghĩa toàn bộ huấn luyện rẻ hơn.','Illustrative reasoning: a replay state starts an imagined trajectory. The actor selects actions, the model predicts states and rewards, and the critic estimates value beyond the rollout. This bootstrap extends the objective beyond directly simulated steps, but the critic is also learned from finite information; it is not a true answer supplied by the environment. Compare policy-learning cost with later action cost when contrasting Dreamer and planning. Fast decisions do not by themselves mean cheaper total training or more accurate dynamics.'),
 dreamerv3:p('Ví dụ diễn giải: một miền có phần thưởng nhỏ, miền khác có phần thưởng lớn và thưa. Quy tắc ổn định nhằm giúp các hạng mục tiêu không mất cân bằng chỉ vì thang số. Đánh giá cấu hình dùng chung cần giữ các lựa chọn thuật toán cố định và báo cáo seed, tài nguyên cùng phiên bản. Nếu chuyển miền thất bại, hãy phân tích khám phá, biểu diễn và động lực riêng. Không thể từ một phép biến đổi số suy ra rằng mọi sai lệch mô hình được xử lý hoặc mọi môi trường đều học được.','Illustrative reasoning: one domain has small rewards while another has large, sparse rewards. Stabilization tries to prevent objective terms from becoming imbalanced merely because of numerical scale. A shared-configuration evaluation keeps algorithm choices fixed and reports seeds, resources, and version. When transfer fails, separate exploration, representation, and dynamics issues. A numerical transformation alone does not establish that all model bias is handled or that every environment can be learned. Robust optimization and accurate predictive knowledge are related but distinct goals.')
};
for(const m of models){const a=m.sections.mechanism,b=walkthrough[m.id];m.sections.mechanism=p(a.vi+'\n\n'+b.vi,a.en+'\n\n'+b.en);}

const principles=[
 {id:'convolution',title:p('Tính cục bộ & Chia sẻ trọng số','Locality & weight sharing'),domain:'Machine learning',formulation:p('Một bộ lọc dùng chung nhận dạng mẫu cục bộ ở nhiều vị trí.','Shared filters detect local structure across positions.'),evidence:[refs.lenet]},
 {id:'variational',title:p('Suy luận biến phân','Variational inference'),domain:'Probability',formulation:p('Tối ưu cận dưới của log likelihood bằng posterior xấp xỉ.','Optimize a log-likelihood lower bound with approximate posteriors.'),evidence:[refs.vae]},
 {id:'adversarial',title:p('Tối ưu đối kháng','Adversarial optimization'),domain:'Optimization',formulation:p('Hai mô hình tối ưu mục tiêu tương tác; không mặc định hội tụ.','Two learners optimize interacting objectives; convergence is not assumed.'),evidence:[refs.gan]},
 {id:'denoising',title:p('Khử nhiễu xác suất','Probabilistic denoising'),domain:'Probability',formulation:p('Học các chuyển tiếp ngược của quá trình thêm nhiễu.','Learn reverse transitions of a corruption process.'),evidence:[refs.ddpm]},
 {id:'control',title:p('Điều khiển dựa trên mô hình','Model-based control'),domain:'Control',formulation:p('Dự đoán động lực và phần thưởng để đánh giá hành động tương lai.','Predict dynamics and rewards to evaluate future actions.'),evidence:[refs.planet,refs.dreamer]}
];
const connections=[];
function edge(source,target,type,status,rationale,evidence){connections.push({id:'edge-'+connections.length,source_model_id:source,target_model_id:target,relationship_type:type,verification_status:status,rationale,evidence});}
edge('alexnet','lenet','inspired_by','verified',p('Tiếp nối CNN và học đặc trưng; quy mô dữ liệu và huấn luyện đã thay đổi.','Continues CNN feature learning with changed data scale and training.'),[refs.alexnet]);
edge('vgg','alexnet','improves','verified',p('Khảo sát mạng sâu và so sánh với thiết kế CNN trước; không phải kế thừa trọng số.','Studies deeper networks against prior CNN designs, not inherited weights.'),[refs.vgg]);
edge('resnet','vgg','inspired_by','verified',p('Bài ResNet mô tả baseline chịu ảnh hưởng VGG, rồi thay đổi cách tham số hóa bằng residual.','The ResNet paper describes a VGG-inspired baseline and changes parameterization with residuals.'),[refs.resnet]);
edge('ldm','ddpm','extends','verified',p('Mở rộng diffusion sang không gian nén và các tác vụ điều kiện.','Extends diffusion to compressed space and conditioning tasks.'),[refs.ldm]);
edge('vae','ldm','method_transfer','verified',p('Chuyển giao autoencoding và latent regularization; không coi mọi first stage là VAE gốc.','Transfers autoencoding and latent regularization; not every first stage is original VAE.'),[refs.ldm]);
edge('vae','world','method_transfer','verified',p('World Models dùng VAE để nén quan sát trước mô hình động lực.','World Models uses a VAE to compress observations before dynamics modeling.'),[refs.world]);
edge('dreamer','planet','extends','verified',p('Dùng nhánh recurrent state-space model và học hành vi trong tưởng tượng thay cho chỉ lập kế hoạch trực tuyến.','Builds on recurrent state-space modeling and learns imagined behavior rather than relying on online planning.'),[refs.dreamer]);
edge('dreamerv3','dreamer','extends','verified',p('Quan hệ cấp họ; DreamerV2 là mốc trung gian chưa có trong mẫu UI.','Family-level relation; intervening DreamerV2 is omitted from this UI sample.'),[refs.dreamerv3]);
edge('ldm','world','mathematical_connection','proposed',p('So sánh vai trò của nén latent trong sinh ảnh và điều khiển. Liên hệ phân tích, không có tuyên bố ảnh hưởng lịch sử.','Compare latent compression for generation and control. Analytical comparison, not a historical-influence claim.'),[]);
function principle(model,id){connections.push({id:'edge-'+connections.length,source_model_id:model,target_principle_id:id,relationship_type:'uses_principle',verification_status:'verified',rationale:p('Nguyên lý được mô tả trong bài gốc.','Principle described in the original paper.'),evidence:[refs[model]]});}
for(const id of ['lenet','alexnet','vgg','resnet'])principle(id,'convolution');
principle('vae','variational');principle('gan','adversarial');principle('ddpm','denoising');principle('ldm','denoising');
for(const id of ['world','planet','dreamer','dreamerv3'])principle(id,'control');
export const sampleAtlas={series,chains,models,principles,connections,papers:models.map(m=>({id:'paper-'+m.id,chain_id:m.chain_id,model_id:m.id,title:refs[m.id].title,url:refs[m.id].url,year:m.year,evidence:[refs[m.id]]}))};
